package com.arenashowdown.lobby;
import net.kyori.adventure.text.Component;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import java.util.*;
final class LobbyMenu implements Listener {
 static final class Holder implements InventoryHolder{private Inventory inventory;public Inventory getInventory(){return inventory;}}
 private final ArenaLobbyPlugin plugin;private final List<String> ids=List.of("corrida","skywars","battle-royale","desafio-de-sorte","parkour","roube-a-bandeira","csgo","tnt-run");private final int[]slots={10,12,14,16,28,30,32,34};
 LobbyMenu(ArenaLobbyPlugin plugin){this.plugin=plugin;}
 void open(Player p){Holder h=new Holder();Inventory inv=Bukkit.createInventory(h,54,plugin.text(plugin.getConfig().getString("gui.title","&6✦ &fARENA SHOWDOWN &8| &eMINIGAMES")));h.inventory=inv;ItemStack border=item(Material.BLACK_STAINED_GLASS_PANE,"&8",List.of());for(int s=0;s<54;s++)if(s<9||s>=45||s%9==0||s%9==8)inv.setItem(s,border);for(int i=0;i<ids.size();i++)inv.setItem(slots[i],game(ids.get(i)));var v=plugin.state().view;inv.setItem(39,item(Material.GOLD_INGOT,"&6Ranking geral",List.of("&7Clique para consultar a classificacao.")));inv.setItem(40,item(Material.NETHER_STAR,"&e"+v.name(),List.of("&7Estado: &f"+v.state(),"&7Rodada: &f"+v.round()+"/"+v.totalRounds(),"&7Proximo: &f"+v.next())));int pos=v.position(p.getUniqueId());inv.setItem(41,item(Material.PLAYER_HEAD,"&f"+p.getName(),List.of("&7Equipe: &f"+empty(v.team(p.getUniqueId()),"Sem equipe"),"&7Ranking: &f"+(pos==0?"Nao classificado":"#"+pos),"&7Pontos: &e"+v.points(p.getUniqueId()))));inv.setItem(45,item(Material.ENDER_PEARL,"&eRetornar ao lobby",List.of("&7Teleporta ao spawn configurado.")));if(p.hasPermission("arena.lobby.admin"))inv.setItem(53,item(Material.LIME_DYE,"&aIniciar proxima rodada",List.of("&7Executa as validacoes do ArenaCore.")));p.openInventory(inv);}
 private ItemStack game(String id){String r="minigames."+id;String arena=plugin.getConfig().getString(r+".arena","");boolean configured=!arena.isBlank(),enabled=plugin.getConfig().getBoolean(r+".enabled")&&(!id.equals("parkour")||plugin.parkourAvailable()),active=plugin.state().view.minigameActive(id);String status=active?"&6Partida em andamento":!enabled?"&cEm desenvolvimento":!configured?"&cArena nao configurada":"&aDisponivel";Material type=Material.matchMaterial(plugin.getConfig().getString(r+".icon","BARRIER"));return item(type==null?Material.BARRIER:type,(enabled&&configured?"&a":"&c")+plugin.getConfig().getString(r+".name",id),List.of("&7"+plugin.getConfig().getString(r+".description","Desafio competitivo."),"","&7Estado: "+status,"&7Minimo: &f"+plugin.getConfig().getInt(r+".min-players",2)+" jogadores","&7Vitoria: &e"+plugin.getConfig().getInt(r+".max-points",10)+" pontos","&7Arena: &f"+empty(arena,"Nao configurada"),"",enabled&&configured&&!active?"&eAdministradores iniciam a rodada.":"&8Consulta somente."));}
 private String empty(String v,String f){return v==null||v.isBlank()?f:v;}private ItemStack item(Material t,String n,List<String>l){ItemStack i=new ItemStack(t);ItemMeta m=i.getItemMeta();m.displayName(plugin.text(n));m.lore(l.stream().map(plugin::text).toList());i.setItemMeta(m);return i;}
 @EventHandler public void click(InventoryClickEvent e){if(!(e.getInventory().getHolder() instanceof Holder))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p)||e.getClickedInventory()==null)return;int s=e.getRawSlot();if(s==39){p.closeInventory();p.performCommand("arena ranking "+plugin.championship());}else if(s==45){p.closeInventory();plugin.returnToLobby(p);}else if(s==53&&p.hasPermission("arena.lobby.admin")){p.closeInventory();Bukkit.dispatchCommand(Bukkit.getConsoleSender(),"arena next "+plugin.championship());}}
 @EventHandler public void drag(InventoryDragEvent e){if(e.getInventory().getHolder() instanceof Holder)e.setCancelled(true);}
}
